import{_ as r,C as n,o as i,c as s,j as t,a,E as d,a2 as l}from"./chunks/framework.DdtnLau3.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Piwork","text":"A shareable, runnable AI workspace","tagline":"Powered by an evolvable Harness.","image":{"src":"/logo.png","alt":"Piwork"},"actions":[{"theme":"brand","text":"Get Started","link":"/guide/quick-start"},{"theme":"alt","text":"Watch Demo","link":"/demo/product-demo.html"},{"theme":"alt","text":"GitHub","link":"https://github.com/pphboy/piwork"},{"theme":"alt","text":"Discussions","link":"https://github.com/pphboy/piwork/discussions"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),p={name:"index.md"};function h(c,e,m,k,u,w){const o=n("ProductDemo");return i(),s("div",null,[e[0]||(e[0]=t("h2",{id:"piwork-in-70-seconds",tabindex:"-1"},[a("Piwork in 70 seconds "),t("a",{class:"header-anchor",href:"#piwork-in-70-seconds","aria-label":'Permalink to "Piwork in 70 seconds"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("AI creates a real content studio, evolves it while preserving existing ideas, and the entire Work moves to another Piwork environment. "),t("a",{href:"/piwork/demo/product-demo.html"},"View the demo and recording details"),a(".")],-1)),d(o),e[2]||(e[2]=l('<h2 id="what-is-piwork" tabindex="-1">What is Piwork? <a class="header-anchor" href="#what-is-piwork" aria-label="Permalink to &quot;What is Piwork?&quot;">​</a></h2><p>Piwork packages a runnable AI workspace into a portable unit called a <strong>Work</strong>. Keep the applications, files, conversation history, and execution environment together, then export them and continue on another Piwork installation.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Role</th></tr></thead><tbody><tr><td><a href="/piwork/concepts/work.html">Work</a></td><td><strong>The workspace.</strong> Holds the environment and its durable state.</td></tr><tr><td><a href="/piwork/concepts/service.html">Service</a></td><td><strong>The capability.</strong> Runs an application, API, or other container service.</td></tr><tr><td><a href="/piwork/concepts/harness.html">Harness</a></td><td><strong>The intelligence.</strong> Uses models, tools, and workspace-specific instructions to understand and operate the Work.</td></tr></tbody></table><p>The Harness can help build and change the workspace it runs in. Its instructions, Skills, packages, and verified experience can evolve with that Work.</p><p>Default Web development uses a reusable Python + NiceGUI + SQLite environment. Standard templates adopt deployed updates automatically; see <a href="/piwork/guide/web-development.html">Web Development</a> for usage and maintenance.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><strong>Create → Run → Evolve → Export → Share → Import → Continue</strong></p><p>Export a stopped Work as a <code>.work</code> file. Import it into a compatible installation and start it explicitly. The target supplies its own model credentials.</p><h2 id="example-kanban-work" tabindex="-1">Example: Kanban Work <a class="header-anchor" href="#example-kanban-work" aria-label="Permalink to &quot;Example: Kanban Work&quot;">​</a></h2><p>A board, its data, an application Service, and a Harness that helps build and operate it form one workspace. <a href="/piwork/demo/kanban.html">Read the Kanban walkthrough</a>. The Kanban example&#39;s downloadable package and recording are still being prepared.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><p><a href="/piwork/guide/quick-start.html">Start Piwork with one command</a>: one Docker container, then open the server IP to configure the administrator, model and CoreRuntime and use the full workbench. No CLI, domain or initialization environment is required. Optional <a href="/piwork/piwork/install/0.0.10-024c864cb667-99aec1718558/docker-compose.yml">docker-compose.yml</a>. State: published. Images are published and anonymously verified.</p>',12))])}const f=r(p,[["render",h]]);export{g as __pageData,f as default};
